const body = $json.body ?? $json;
const text = typeof body.original_input === 'string' ? body.original_input.trim() : '';
const requestId = body.request_id || $execution.id || `truthlens-${Date.now()}`;
if (!text) return [{ json: { valid: false, request_id: requestId, error: { code: 'INVALID_INPUT', message: 'original_input is required' } } }];
return [{ json: { valid: true, request_id: requestId, original_input: text, mode: body.mode || 'standard', received_at: new Date().toISOString() } }];

const input = $('Validate and correlate request').first().json;
const response = $json;
const apiError = response.error || response.statusCode >= 400 || !Array.isArray(response.claims);
const claims = Array.isArray(response.claims) ? response.claims : [];
const reasons = [];
if (apiError) reasons.push(response.error?.code || 'API_FAILURE');
for (const claim of claims) {
  if (claim.verdict === 'CONTRADICTED') reasons.push('CONTRADICTED');
  if (claim.verdict === 'INSUFFICIENT_EVIDENCE' && claim.evidence_strength !== 'HIGH') reasons.push('INSUFFICIENT_EVIDENCE_LOW_STRENGTH');
  if (claim.conflicting_evidence === true) reasons.push('CONFLICTING_EVIDENCE');
  if (claim.evidence_strength === 'LOW') reasons.push('LOW_EVIDENCE_STRENGTH');
}
const provider = response.provider || 'unavailable';
if (/fallback|demo/i.test(provider) && input.mode !== 'demo') reasons.push('FALLBACK_OR_UNAVAILABLE_PROVIDER');
return [{json: {request_id: input.request_id, received_at: input.received_at, original_input: input.original_input, mode: input.mode, analysis: response, processing_error: apiError, requires_review: reasons.length > 0, escalation_reasons: [...new Set(reasons)], provider, fallback_detected: /fallback|demo/i.test(provider)}}];

const report = $json.analysis || {};
const claims = Array.isArray(report.claims) ? report.claims : [];
return [{json: {request_id: $json.request_id, analysis_id: report.analysis_id || null, timestamp: new Date().toISOString(), original_input: $json.original_input, provider: report.provider || null, mode: report.mode || $json.mode, fallback_detected: $json.fallback_detected, escalation_reason: $json.escalation_reasons, claims: claims.map(claim => ({claim_id: claim.id, claim_text: claim.claim, verdict: claim.verdict, evidence_strength: claim.evidence_strength, confidence: null, citations: claim.evidence || [], supporting_evidence: (claim.evidence || []).filter(item => item.relationship === 'supports'), contradicting_evidence: (claim.evidence || []).filter(item => item.relationship === 'contradicts'), corrections: claim.corrected_statement ? [claim.corrected_statement] : []}))}}];
